import React from 'react';
import { PROJECTS } from '../data/projects';

function ProjectComponent(props) {
    const {title, subtitle, img, desc, github, link, tech} = props.self;

    return(
        <div className="row projectRow">
            <div className="d-none d-md-block col-md-4 projectImgContainer">
                <div className="projectImg" style={{backgroundImage: `url("${img}")`}} />
            </div>
            <div className="col-12 col-md-8">
                <div className="row">
                    <div className="col-12">
                        <h4>{title}</h4>
                    </div>
                    <div className="col-12">
                        <h6 style={{color:'#888'}}>{subtitle}</h6>
                    </div>
                    {tech && <div className="col-12">
                        <div className="tech-tags">
                            {tech.map(t => <span key={t} className="tech-tag">{t}</span>)}
                        </div>
                    </div>}
                    <div className="col-12" style={{marginTop:8}}>
                        <p>{desc}</p>
                    </div>
                    <div className="col-12">
                        {github && <a className="project-link" href={github} target="_blank" rel="noopener noreferrer"><i className="fa fa-github"/> Code</a>}
                        {link && <a className="project-link project-link-demo" href={link} target="_blank" rel="noopener noreferrer"><i className="fa fa-external-link"/> Live Demo</a>}
                    </div>
                </div>
            </div>
        </div>
    )
}

function ProjectsComponent(props) {
    const projectsUI = PROJECTS.map(project => <ProjectComponent self={project} key={project.id}/>); 

    return(
        <div className="container">
            <div className="row">
                <h1 className="col-12 projectHeading">Selected Projects</h1>
            </div>
            {projectsUI}
        </div>
    );
}

export default ProjectsComponent;
